let offset = 70
let minGap = 12
let prevRight = null
for V in objects {
  let tentative = V.x + offset
  if prevRight == null {
    move V to (tentative, 100)
    prevRight = tentative + V.w
  } else {
    let needed = max(tentative, prevRight + minGap)
    move V to (needed, 100)
    prevRight = needed + V.w
  }
}
